const radios = code.match(/<input[^>]*type=["']radio["'][^>]*>/gi) ?? [];
if (radios.length !== 3) throw new Error(`Expected three radio inputs, found ${radios.length}.`);
if (!radios.every((r) => /name=["']size["']/i.test(r))) {
  throw new Error("All three radios must share name=\"size\" — that's what makes them exclusive.");
}

const values = (code.match(/<input[^>]*type=["']radio["'][^>]*>/gi) ?? [])
  .map((r) => (r.match(/value=["']([^"']*)["']/i) ?? [])[1]);
for (const v of ["s", "m", "l"]) {
  if (!values.includes(v)) throw new Error(`A radio with value="${v}" is missing.`);
}

const boxes = code.match(/<input[^>]*type=["']checkbox["'][^>]*>/gi) ?? [];
if (boxes.length !== 1) throw new Error(`Expected one checkbox, found ${boxes.length}.`);
if (!/name=["']gift["']/i.test(boxes[0])) throw new Error("The checkbox needs name=\"gift\".");
if (!/value=["']yes["']/i.test(boxes[0])) throw new Error("The checkbox needs value=\"yes\".");

const ids = [...code.matchAll(/<input[^>]*id=["']([^"']*)["']/gi)].map((m) => m[1]);
if (ids.length < 4) throw new Error("Give every control an id.");
for (const id of ids) {
  if (!new RegExp(`for=["']${id}["']`, "i").test(code)) {
    throw new Error(`The control with id="${id}" has no label wired with for="${id}".`);
  }
}
